contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val, uint laterVal) public payable {
        require(true);

        // Initial state: observe MinSum before anything
        uint beforeMin = c.MinSum(); if (__ESBMC_reverted()) return;

        // Mark the contract as initialized
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Attempt to change MinSum after initialization
        bool reverted;
        c.SetMinSum(laterVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Rule: after Initialized(), SetMinSum must revert and MinSum must remain unchanged.
        assert(reverted && c.MinSum() == beforeMin);
    }

    receive() external payable {}
}

