pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val, uint256 laterVal) internal {
        vm.assume(true);
        uint256 beforeMin;
        try c.MinSum() returns (uint256 __r) { beforeMin = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(laterVal) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.MinSum() == beforeMin);
    }

    function testFuzz_run(uint256 val, uint256 laterVal) public {
        _run(val, laterVal);
    }

    receive() external payable {}
}
